import React from 'react';

const Experience = () => {
    return (
        <div className="experience">
            <h3>Expériences</h3>
            <div className="exp-1">
                <h4>Data Scientist - Tereos</h4>
                <h5>Janv.2019 - Aujourd'hui</h5>
                <p>Mise en place d'un référenciel Data Science au sein du Groupe. Déployement des modèles Data Science sur Azure.
                    Accompagnement des Greens Belts, Coaching et formation Data Science.
                </p>
            </div>
            <div className="exp-2">
                <h4>Projet Data Sience (NLP) - TALAN SOLUTION</h4>
                <h5>sept.2017 - févr.2018</h5>
                <p>encadrer l'étudiant dans ces tâches quotidiennes durant son stage de 4ème année en tant que Data Scientist. 
                    L'orienter, Acc vers des pistes d'amélioration afin de mieux répondre à son besoin à l'instant T. 
                    Facilité son intégration dans l'entreprise. Assurer un accompagnement pédagogique. 
                    Recevoir l'étudiant, évaluer sa progression et les pré-requis. 
                    Réalisation des entretiens réguliers et des moments de réflexion avec l'étudiant.
                </p>
            </div>
        </div>
    );
};

export default Experience;
